package com.gerenciadorrural.shared.tenancy;
import org.junit.jupiter.api.Test; import org.springframework.mock.web.MockHttpServletRequest; import java.util.*; import java.util.concurrent.*; import static org.assertj.core.api.Assertions.assertThat;
class RequestTenantContextProviderTest {
 @Test void readsOnlyTheCurrentRequestAttribute(){var request=new MockHttpServletRequest();var provider=new RequestTenantContextProvider(request); assertThat(provider.currentContext()).isEmpty(); var context=context("VIEWER","ALL_FARMS");request.setAttribute(TenantContextRequestAttribute.NAME,context);assertThat(provider.requireCurrent()).isSameAs(context);}
 @Test void separateRequestsDoNotRetainOrShareContexts(){var first=new MockHttpServletRequest();var second=new MockHttpServletRequest();var a=context("OWNER","ALL_FARMS");var b=context("VIEWER","SELECTED_FARMS");first.setAttribute(TenantContextRequestAttribute.NAME,a);second.setAttribute(TenantContextRequestAttribute.NAME,b);assertThat(new RequestTenantContextProvider(first).requireCurrent()).isSameAs(a);assertThat(new RequestTenantContextProvider(second).requireCurrent()).isSameAs(b).isNotSameAs(a);assertThat(new RequestTenantContextProvider(new MockHttpServletRequest()).currentContext()).isEmpty();}
 @Test void concurrentRequestsObserveOnlyTheirOwnRequestAttribute() throws Exception {var gate=new CyclicBarrier(2);var done=new CountDownLatch(2);var contexts=Collections.synchronizedList(new ArrayList<TenantContext>());var a=context("OWNER","ALL_FARMS");var b=context("VIEWER","SELECTED_FARMS");ExecutorService pool=Executors.newFixedThreadPool(2);for(var value:List.of(a,b))pool.submit(()->{try{var request=new MockHttpServletRequest();request.setAttribute(TenantContextRequestAttribute.NAME,value);gate.await();contexts.add(new RequestTenantContextProvider(request).requireCurrent());}catch(Exception e){throw new RuntimeException(e);}finally{done.countDown();}});assertThat(done.await(5,TimeUnit.SECONDS)).isTrue();pool.shutdownNow();assertThat(contexts).containsExactlyInAnyOrder(a,b).doesNotContainNull();assertThat(contexts.get(0)).isNotSameAs(contexts.get(1));}
 private static TenantContext context(String role,String scope){return new TenantContext(new TenantId(UUID.randomUUID()),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),role,scope);}
}
